3	import fs from 'fs';
4	import path from 'path';
5	import process from 'process';
6	import { execSync } from 'child_process';
7	import { createRequire } from 'module';
8	
9	import { Command } from 'commander';
10	import inquirer from 'inquirer';
11	
12	import {
13	  Config,
14	  Documents,
15	  Eval,
16	  Finetune,
17	  Providers,
18	  Questionnaire,
19	  Rag,
20	  Scanners
21	} from 'frai-core';
22	
23	const require = createRequire(import.meta.url);
24	const pkg = require('../package.json') as { version?: string; name?: string };
25	
26	type LogLevel = 'info' | 'success' | 'warn' | 'error';
27	type LogMeta = Record<string, unknown> | undefined;
28	
29	const DOC_FILENAMES = ['checklist.md', 'model_card.md', 'risk_file.md'];
30	const LOCAL_ENV_DISPLAY = '.env';
31	const GLOBAL_CONFIG_DISPLAY = '~/.config/frai/config';
32	
33	type ScanResult = ReturnType<typeof Scanners.scanCodebase>;
34	
35	interface GenerateOptions {
36	  scan?: boolean;
37	  ci?: boolean;
38	  key?: string;
39	  global?: boolean;
40	  exportPdf?: boolean;
41	  showConfig?: boolean;
42	}
43	
44	interface ScanOptions {
45	  root?: string;
46	  ci?: boolean;
47	  json?: boolean;
48	  silent?: boolean;
49	}
50	
51	interface EvalOptions {
52	  outputs: string;
53	  references?: string;
54	  report?: string;
55	  format?: 'json' | 'markdown';
56	}
57	
58	interface RagOptions {
59	  input?: string | string[];
60	  output?: string;
61	  chunkSize?: number;
62	  extensions?: string[];
63	}
64	
65	interface FinetuneTemplateOptions {
66	  output?: string;
67	}
68	
69	interface FinetuneValidateOptions {
70	  readiness?: boolean;
71	}
72	
73	const log = {
74	  info(message: string, meta?: LogMeta) {
75	    console.log(formatLog('info', message, meta));
76	  },
77	  success(message: string, meta?: LogMeta) {
78	    console.log(formatLog('success', message, meta));
79	  },
80	  warn(message: string, meta?: LogMeta) {
81	    console.warn(formatLog('warn', message, meta));
82	  },
83	  error(message: string, meta?: LogMeta) {
84	    console.error(formatLog('error', message, meta));
85	  }
86	};
87	
88	function formatLog(level: LogLevel, message: string, meta: LogMeta = undefined) {
89	  const timestamp = new Date().toISOString();
90	  if (!meta || Object.keys(meta).length === 0) {
91	    return `[${timestamp}] ${level.toUpperCase()} ${message}`;
92	  }
93	  let serializedMeta = '';
94	  try {
95	    serializedMeta = JSON.stringify(meta);
96	  } catch (error) {
97	    serializedMeta = String(meta);
98	  }
99	  return `[${timestamp}] ${level.toUpperCase()} ${message} ${serializedMeta}`;
100	}
101	
102	function listDocs() {
103	  const cwd = process.cwd();
104	  const items = DOC_FILENAMES.filter((file) => fs.existsSync(path.join(cwd, file)));
105	  if (!items.length) {
106	    log.info('No documentation files detected in current directory.', { cwd });
107	    return;
108	  }
109	  log.info('Documentation files found:', { files: items });
110	  items.forEach((file) => console.log(`  - ${file}`));
111	}
112	
113	function cleanDocs() {
114	  const cwd = process.cwd();
115	  let removed = 0;
116	  for (const file of DOC_FILENAMES) {
117	    const target = path.join(cwd, file);
118	    if (fs.existsSync(target)) {
119	      fs.unlinkSync(target);
120	      removed += 1;
121	      log.info(`Removed ${file}`);
122	    }
123	  }
124	  if (!removed) {
125	    log.info('No documentation files to remove.');
126	  } else {
127	    log.success('Documentation directory cleaned.', { removed });
128	  }
129	}
130	
131	function exportDocsAsPdf() {
132	  const existing = DOC_FILENAMES.filter((file) => fs.existsSync(file));
133	  if (!existing.length) {
134	    log.warn('No documentation files to export.');
135	    return;
136	  }
137	  try {
138	    execSync(`npx markdown-pdf ${existing.join(' ')}`, { stdio: 'inherit' });
139	    log.success('PDF export complete.');
140	  } catch (error) {
141	    log.error('Failed to export documentation as PDF.', {
142	      error: error instanceof Error ? error.message : String(error)
143	    });
144	  }
145	}
146	
147	function showConfigStatus() {
148	  const local = {
149	    exists: Config.hasLocalApiKey(),
150	    value: Config.getLocalApiKey()
151	  };
152	  const global = {
153	    exists: Config.hasGlobalApiKey(),
154	    value: Config.getGlobalApiKey()
155	  };
156	
157	  const status = {
158	    local: {
159	      configured: local.exists,
160	      location: LOCAL_ENV_DISPLAY
161	    },
162	    global: {
163	      configured: global.exists,
164	      location: GLOBAL_CONFIG_DISPLAY
165	    }
166	  };
167	
168	  log.info('API key configuration status', status);
169	  if (local.exists) {
170	    log.info('Local API key detected (masked).');
171	  }
172	  if (global.exists) {
173	    log.info('Global API key detected (masked).');
174	  }
175	  if (!local.exists && !global.exists) {
176	    log.warn('No OpenAI API key configured. Some AI powered features will be unavailable.');
177	  }
178	}
179	
180	async function configureApiKeyIfProvided(key?: string, scopeGlobal = false) {
181	  if (!key) return;
182	  if (scopeGlobal) {
183	    Config.setGlobalApiKey(key);
184	    log.success('Stored OpenAI API key in global configuration.', { location: GLOBAL_CONFIG_DISPLAY });
185	  } else {
186	    Config.setLocalApiKey(key);
187	    log.success('Stored OpenAI API key in local configuration.', { location: LOCAL_ENV_DISPLAY });
188	  }
189	}
190	
191	function resolveConfiguredApiKey() {
192	  const local = Config.getLocalApiKey();
193	  if (local) return local;
194	  return Config.getGlobalApiKey();
195	}
196	
197	async function promptForApiKey(scopeGlobal?: boolean) {
198	  const answers = await inquirer.prompt<{ apiKey: string }>([
199	    {
200	      type: 'password',
201	      name: 'apiKey',
202	      message: `Enter your OpenAI API key (${scopeGlobal ? 'global' : 'local'} storage):`,
203	      mask: '*',
204	      validate: (value) => Boolean(value?.trim()) || 'API key is required.'
205	    }
206	  ]);
207	  await configureApiKeyIfProvided(answers.apiKey, scopeGlobal);
208	  return answers.apiKey;
209	}
210	
211	function summarizeScanResult(scan: ScanResult | null) {
212	  if (!scan) return '';
213	  const libraryEntries = (Object.entries(scan.aiLibraryMatches ?? {}) as Array<[string, number]>).sort(
214	    (a, b) => b[1] - a[1]
215	  );
216	  const functionEntries = (Object.entries(scan.aiFunctionMatches ?? {}) as Array<[string, number]>).sort(
217	    (a, b) => b[1] - a[1]
218	  );
219	  const libraries = libraryEntries.slice(0, 5).map(([name, count]) => `${name} (${count})`).join(', ');
220	  const functions = functionEntries.slice(0, 5).map(([name, count]) => `${name} (${count})`).join(', ');
221	
222	  return [
223	    `Detected ${scan.aiFiles.length} AI related files out of ${scan.totalFiles} scanned.`,
224	    libraries ? `Top libraries: ${libraries}` : 'No AI libraries detected.',
225	    functions ? `Top functions: ${functions}` : 'No AI-specific functions detected.'
226	  ].join('\n');
227	}
228	
229	function runScanCommand({ root = process.cwd(), ci = false, json = false, silent = false }: ScanOptions) {
230	  const result = Scanners.scanCodebase({ root });
231	
232	  if (json) {
233	    console.log(JSON.stringify(result, null, 2));
234	    return result;
235	  }
236	
237	  if (!silent) {
238	    log.info('Scan completed.', {
239	      totalFiles: result.totalFiles,
240	      aiFiles: result.aiFiles.length
241	    });
242	    if (result.aiFiles.length) {
243	      console.log('AI-related files:');
244	      result.aiFiles.forEach((file) => console.log(`  - ${path.relative(root, file)}`));
245	    }
246	    if (!result.aiFiles.length) {
247	      log.info('No AI indicators detected in scope.');
248	    }
249	    if (ci) {
250	      log.info('CI mode: exiting after scan.');
251	    }
252	  }
253	
254	  return result;
255	}
256	
257	type FetchLike = (input: unknown, init?: unknown) => Promise<unknown>;
258	
259	let cachedFetch: FetchLike | null = null;
260	
261	async function resolveFetchImplementation(): Promise<FetchLike> {
262	  if (typeof (globalThis as { fetch?: FetchLike }).fetch === 'function') {
263	    return (globalThis as { fetch: FetchLike }).fetch.bind(globalThis);
264	  }
265	  if (cachedFetch) return cachedFetch;
266	  const mod = await import('node-fetch');
267	  cachedFetch = (mod.default ?? mod) as FetchLike;
268	  return cachedFetch;
269	}
270	
271	async function generateAITips(answers: Awaited<ReturnType<typeof Questionnaire.runQuestionnaire>>, apiKey: string | null, scan: ScanResult | null) {
272	  if (!apiKey) {
273	    return null;
274	  }
275	  try {
276	    const fetchImpl = await resolveFetchImplementation();
277	    const provider = (Providers.createProvider as unknown as (config: unknown) => any)({
278	      apiKey,
279	      fetch: fetchImpl
280	    });
281	    const context = Documents.buildContextForAITips(answers);
282	    const scanSummary = summarizeScanResult(scan);
283	    const prompt = [
284	      'You are an expert in responsible AI implementation.',
285	      'Provide three actionable recommendations for each documentation artefact (checklist, model card, risk file).',
286	      'Ground the advice in the following feature context and scan summary.'
287	    ].join(' ');
288	
289	    const userContent = [
290	      'AI Feature Context:',
291	      context,
292	      '',
293	      'Scan Summary:',
294	      scanSummary || 'No automated scan results were available.'
295	    ].join('\n');
296	
297	    const response = await provider.chatCompletion({
298	      messages: [
299	        {
300	          role: 'system',
301	          content: prompt
302	        },
303	        {
304	          role: 'user',
305	          content: userContent
306	        }
307	      ],
308	      temperature: 0.3,
309	      maxTokens: 800
310	    });
311	
312	    if (!response?.content) return null;
313	    return String(response.content).trim();
314	  } catch (error) {
315	    log.warn('Unable to generate AI assistance tips. Continuing without them.', {
316	      error: error instanceof Error ? error.message : String(error)
317	    });
318	    return null;
319	  }
320	}
321	
322	function extractTips(markdown: string | null) {
323	  const sections = {
324	    checklist: '',
325	    modelCard: '',
326	    riskFile: ''
327	  };
328	
329	  if (!markdown) {
330	    return sections;
331	  }
332	
333	  type SectionKey = keyof typeof sections;
334	  const markers: Record<string, SectionKey> = {
335	    'checklist tips': 'checklist',
336	    'model card tips': 'modelCard',
337	    'risk file tips': 'riskFile'
338	  };
339	
340	  let current: SectionKey | null = null;
341	  const lines = markdown.split('\n');
342	  for (const line of lines) {
343	    const normalized = line.trim().toLowerCase();
344	    const key = normalized.replace(/[:\s]+$/u, '');
345	    const sectionKey = markers[key];
346	    if (sectionKey) {
347	      current = sectionKey;
348	      sections[sectionKey] = '';
349	      continue;
350	    }
351	    if (current) {
352	      sections[current] = `${sections[current]}${line}\n`;
353	    }
354	  }
355	
356	  for (const key of Object.keys(sections) as SectionKey[]) {
357	    sections[key] = sections[key].trim();
358	  }
359	
360	  return sections;
361	}
362	
363	async function runGenerateFlow(options: GenerateOptions) {
364	  await configureApiKeyIfProvided(options.key, options.global);
365	  const apiKey = resolveConfiguredApiKey();
366	
367	  if (options.showConfig) {
368	    showConfigStatus();
369	  }
370	
371	  let scanResult: ScanResult | null = null;
372	  if (options.scan || options.ci) {
373	    scanResult = runScanCommand({ ci: options.ci, silent: false });
374	    if ((!scanResult || scanResult.aiFiles.length === 0) && options.ci) {
375	      log.info('CI mode completed with no AI code detected. Exiting without generating documentation.');
376	      return;
377	    }
378	    if (scanResult && scanResult.aiFiles.length === 0 && !options.ci) {
379	      const { proceed } = await inquirer.prompt<{ proceed: boolean }>([
380	        {
