function parseThresholds(thresholdStrings?: string[]): Record<string, number> | undefined {
  if (!thresholdStrings || thresholdStrings.length === 0) {
    return undefined;
  }

  const thresholds: Record<string, number> = {};
  for (const thresholdStr of thresholdStrings) {
    const match = thresholdStr.match(/^([a-z_]+)=([0-9.]+)$/);
    if (!match) {
      log.error(`Malformed threshold: ${thresholdStr}. Expected format: <metric>=<number>`);
      process.exit(2);
    }
    const metricId = match[1];
    const minValue = parseFloat(match[2]);
    if (isNaN(minValue) || minValue < 0 || minValue > 1) {
      log.error(`Invalid threshold value for ${metricId}: ${match[2]}. Must be a number between 0 and 1.`);
      process.exit(2);
    }
    thresholds[metricId] = minValue;
  }
  return thresholds;
}

function runEvalCommand(options: EvalOptions) {
  assertFileExists(options.outputs);
  const dataset = (Eval.loadDataset as unknown as (config: unknown) => any)({
    outputsPath: options.outputs,
    referencesPath: options.references
  });
  const evaluations = (Eval.runEvaluations as unknown as (config: unknown) => any)({
    outputs: dataset.outputs,
    references: dataset.references
  });

  const thresholds = parseThresholds(options.threshold);

  // Validate thresholds against known metrics
  if (thresholds) {
    const validationErrors = (Eval.validateThresholds as unknown as (thresholds: unknown, metrics: unknown) => string[])(
      thresholds,
      evaluations
    );
    if (validationErrors.length > 0) {
      validationErrors.forEach((error) => log.error(error));
      const validMetricIds = evaluations.map((m: any) => m.id).join(', ');
      log.error(`Valid metric IDs are: ${validMetricIds}`);
      process.exit(2);
    }
  }

  const report = (Eval.generateReport as unknown as (config: unknown) => any)({
    evaluations,
    outputsPath: dataset.outputsPath,
    referencesPath: dataset.referencesPath,
    thresholds
  });
  const resolvedPath = (Eval.writeReport as unknown as (config: unknown) => string)({
    report,
    format: options.format ?? 'json',
    reportPath: options.report
  });
  log.success('Evaluation report generated.', { path: resolvedPath });

  // Exit with appropriate code based on threshold results
  if (report.passed === false) {
    process.exit(1);
  }
}

