import fs from 'fs';
import path from 'path';

import {
  DEFAULT_METRICS,
  exactMatchMetric,
  lengthVarianceMetric,
  toxicityMetric
} from './metrics.js';
import { resolveReportPath, toJson, toMarkdown } from './reporters.js';

const defaultFs = fs;

const ensureArray = (value) => (Array.isArray(value) ? value : []);

export function loadDataset({ outputsPath, referencesPath, fs: fsModule = defaultFs } = {}) {
  if (!outputsPath) {
    throw new Error('outputsPath is required for evaluation.');
  }

  const outputsAbsolute = path.resolve(outputsPath);
  const outputsRaw = fsModule.readFileSync(outputsAbsolute, 'utf8');
  const outputs = JSON.parse(outputsRaw);

  let references = [];
  let referencesAbsolute = null;
  if (referencesPath) {
    referencesAbsolute = path.resolve(referencesPath);
    const referencesRaw = fsModule.readFileSync(referencesAbsolute, 'utf8');
    references = JSON.parse(referencesRaw);
  }

  return {
    outputs,
    references,
    outputsPath: outputsAbsolute,
    referencesPath: referencesAbsolute
  };
}

export function runEvaluations({
  outputs,
  references,
  metrics = DEFAULT_METRICS
} = {}) {
  const outs = ensureArray(outputs);
  const refs = ensureArray(references);

  const evaluations = metrics.map((metric) => {
    if (typeof metric === 'function') {
      return metric(outs, refs);
    }
    if (metric && typeof metric.evaluate === 'function') {
      return metric.evaluate(outs, refs);
    }
    throw new Error('Invalid metric supplied to runEvaluations.');
  });

  return evaluations;
}

function validateThresholds(thresholds, metrics) {
  const errors = [];
  const knownMetricIds = metrics.map((m) => m.id);

  for (const [metricId, minValue] of Object.entries(thresholds ?? {})) {
    if (typeof minValue !== 'number') {
      errors.push(`Threshold for ${metricId} must be a number, got ${typeof minValue}`);
    } else if (minValue < 0 || minValue > 1) {
      errors.push(`Threshold for ${metricId} must be between 0 and 1, got ${minValue}`);
    }
    if (!knownMetricIds.includes(metricId)) {
      errors.push(`Unknown metric: ${metricId}. Valid metrics are: ${knownMetricIds.join(', ')}`);
    }
  }

  return errors;
}

function evaluateThresholds(thresholds, metrics) {
  const results = [];
  for (const [metricId, min] of Object.entries(thresholds ?? {})) {
    const metric = metrics.find((m) => m.id === metricId);
    const score = metric?.score;
    const passed = score !== null && score !== undefined && score >= min;
    results.push({
      metric: metricId,
      min,
      score: score ?? null,
      passed
    });
  }
  return results;
}

export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  thresholds,

